mod api; mod ml; mod theme;
use api::{Account, Order, Product, State};
use eframe::egui::{self, Color32, RichText};
use std::sync::mpsc;

fn main()->eframe::Result<()> { eframe::run_native("Goodstock Hardware",eframe::NativeOptions{viewport:egui::ViewportBuilder::default().with_inner_size([1280.0,800.0]).with_min_inner_size([800.0,600.0]),..Default::default()},Box::new(|cc|{theme::apply(&cc.egui_ctx,false);Ok(Box::new(App::new()))})) }
#[derive(PartialEq,Clone,Copy)] enum Page {Home,Shop,History,Overview,Inventory,Pos,Forecast}
struct App { state:State, safe_save:bool, status:String, page:Page, dark:bool, category:String, search:String, in_stock:bool, sort:usize, details:Option<usize>, cart:Vec<(String,i32)>, drawer:bool, delivery:usize, email:String, password:String, signed_in:String, register:bool, login:bool, pos_search:String, pos_cart:Vec<(String,i32)>, tender:usize, cash:f64, new_product:Product, models:Option<ml::Models>, scenario:[f64;4], model:usize, sync:Option<mpsc::Receiver<Result<Vec<serde_json::Value>,String>>> }
impl App {
fn new()->Self {let (state,status)=State::load();let safe_save=!status.starts_with("Could not read state"); Self{state,safe_save,status,page:Page::Home,dark:false,category:"All".into(),search:String::new(),in_stock:false,sort:0,details:None,cart:vec![],drawer:false,delivery:0,email:String::new(),password:String::new(),signed_in:String::new(),register:false,login:false,pos_search:String::new(),pos_cart:vec![],tender:0,cash:0.0,new_product:Product{sku:String::new(),name:String::new(),category:"Tools".into(),description:String::new(),price:0.0,cost:0.0,stock:0,max_stock:40},models:None,scenario:[150.0,0.0,1.0,60.0],model:1,sync:None} }
fn save(&mut self) {if self.safe_save {if let Err(e)=self.state.save(){self.status=format!("Save failed: {e}")}}}
fn total(&self,cart:&[(String,i32)])->f64 {cart.iter().filter_map(|(sku,q)|self.state.products.iter().find(|p|p.sku==*sku).map(|p|p.price*(*q as f64))).sum()}
fn add(cart:&mut Vec<(String,i32)>, p:&Product) {let count=cart.iter().find(|(s,_)|s==&p.sku).map_or(0,|(_,q)|*q); if count<p.stock {if let Some((_,q))=cart.iter_mut().find(|(s,_)|s==&p.sku){*q+=1}else{cart.push((p.sku.clone(),1))}}}
fn checkout(&mut self,pos:bool) {let cart=if pos {&self.pos_cart}else{&self.cart}; if cart.is_empty(){self.status="Add an item first".into();return} if cart.iter().any(|(s,q)|*q<=0 || self.state.products.iter().find(|p|p.sku==*s).map_or(true,|p|p.stock<*q)) {self.status="Stock changed; update quantities before checkout".into();return} let total=self.total(cart); if pos && self.tender==0 && self.cash<total {self.status="Cash received is less than the total".into();return} let items:Vec<_>=cart.iter().map(|(s,q)| {let p=self.state.products.iter().find(|p|p.sku==*s).unwrap();(s.clone(),*q,p.price)}).collect();for (sku,q,_) in &items {if let Some(p)=self.state.products.iter_mut().find(|p|p.sku==*sku){p.stock-=q;}} let number=if pos {let n=self.state.next_pos;self.state.next_pos+=1;format!("GS-POS-{n:04}")} else {let n=self.state.next_order;self.state.next_order+=1;format!("GS-ORD-{n:04}")};let method=if pos { ["Cash","GCash QR","Card"][self.tender] } else { ["Counter Pickup","Local Courier Delivery"][self.delivery] };self.state.orders.push(Order{number:number.clone(),items,total,method:method.into(),customer:self.signed_in.clone()});if pos {self.pos_cart.clear()}else{self.cart.clear();self.drawer=false} self.status=format!("{number} recorded · PHP {total:.2}");self.save(); }
fn nav(&mut self,ui:&mut egui::Ui,p:Page,label:&str) {if ui.selectable_label(self.page==p,label).clicked(){self.page=p;}}
fn catalog(&mut self,ui:&mut egui::Ui) {ui.heading("Shop hardware");ui.label("Find the right parts for your next project.");ui.add_space(10.0);ui.horizontal_wrapped(|ui|{for cat in ["All","Fasteners","Tools","Power & Electrical"] {if ui.selectable_label(self.category==cat,cat).clicked(){self.category=cat.into()}}});ui.horizontal(|ui|{ui.label("Search");ui.text_edit_singleline(&mut self.search);ui.checkbox(&mut self.in_stock,"In stock only");egui::ComboBox::from_id_salt("sort").selected_text(["Featured","Price: low to high","Price: high to low","Name"][self.sort]).show_ui(ui,|ui|{for (i,s) in ["Featured","Price: low to high","Price: high to low","Name"].iter().enumerate(){ui.selectable_value(&mut self.sort,i,*s);}});});let q=self.search.to_lowercase();let mut ids:Vec<usize>=self.state.products.iter().enumerate().filter(|(_,p)|(self.category=="All"||p.category==self.category)&&(!self.in_stock||p.stock>0)&&(p.name.to_lowercase().contains(&q)||p.sku.to_lowercase().contains(&q))).map(|(i,_)|i).collect();match self.sort {1=>ids.sort_by(|a,b|self.state.products[*a].price.total_cmp(&self.state.products[*b].price)),2=>ids.sort_by(|a,b|self.state.products[*b].price.total_cmp(&self.state.products[*a].price)),3=>ids.sort_by(|a,b|self.state.products[*a].name.cmp(&self.state.products[*b].name)),_=>{}} egui::ScrollArea::vertical().show(ui,|ui|{for chunk in ids.chunks(2) {ui.columns(2,|cols|{for (col,&i) in chunk.iter().enumerate(){let p=&self.state.products[i];egui::Frame::group(cols[col].style()).show(&mut cols[col],|ui|{ui.set_min_height(130.0);ui.label(RichText::new(&p.category).small());ui.label(RichText::new(&p.name).strong());ui.label(format!("{}  ·  {} in stock",p.sku,p.stock));ui.label(RichText::new(format!("PHP {:.2}",p.price)).strong());ui.horizontal(|ui|{if ui.button("Specifications").clicked(){self.details=Some(i)} if ui.add_enabled(p.stock>0,egui::Button::new("Add to cart")).clicked(){Self::add(&mut self.cart,p);}});});}});ui.add_space(8.0);}}); }
fn inventory(&mut self,ui:&mut egui::Ui) {ui.heading("Inventory & Pricing");ui.label("Edit values directly. Replenishment fills stock to its target.");let mut changed=false;egui::ScrollArea::both().id_salt("inventory").show(ui,|ui|{egui::Grid::new("stock_table").striped(true).min_col_width(75.0).show(ui,|ui|{for h in ["SKU / Product","Cost PHP","Retail PHP","Markup","Stock","Target","Replenish","Adjust"] {ui.strong(h);}ui.end_row();for p in &mut self.state.products {ui.label(format!("{}\n{}",p.sku,p.name));changed|=ui.add(egui::DragValue::new(&mut p.cost).range(0.0..=1_000_000.0).speed(1.0)).changed();changed|=ui.add(egui::DragValue::new(&mut p.price).range(0.0..=1_000_000.0).speed(1.0)).changed();let amount=((p.price-p.cost)*100.0).round()/100.0;let pct=if p.cost>0.0 {format!("{:.2}%",((amount/p.cost)*10000.0).round()/100.0)}else{"—".into()};ui.label(format!("{amount:.2} / {pct}"));ui.label(p.stock.to_string());changed|=ui.add(egui::DragValue::new(&mut p.max_stock).range(0..=1_000_000)).changed();ui.label((p.max_stock-p.stock.max(0)).max(0).to_string());ui.horizontal(|ui|{if ui.button("−").clicked()&&p.stock>0{p.stock-=1;changed=true}if ui.button("+").clicked(){p.stock+=1;changed=true}});ui.end_row();}});});ui.separator();ui.collapsing("Add New SKU",|ui|{ui.horizontal(|ui|{ui.label("SKU");ui.text_edit_singleline(&mut self.new_product.sku);ui.label("Name");ui.text_edit_singleline(&mut self.new_product.name);});ui.horizontal(|ui|{ui.label("Category");ui.text_edit_singleline(&mut self.new_product.category);ui.label("Description");ui.text_edit_singleline(&mut self.new_product.description);});ui.horizontal(|ui|{ui.label("Cost");ui.add(egui::DragValue::new(&mut self.new_product.cost).range(0.0..=1_000_000.0));ui.label("Retail");ui.add(egui::DragValue::new(&mut self.new_product.price).range(0.0..=1_000_000.0));ui.label("Stock");ui.add(egui::DragValue::new(&mut self.new_product.stock).range(0..=1_000_000));ui.label("Target");ui.add(egui::DragValue::new(&mut self.new_product.max_stock).range(0..=1_000_000));});if ui.button("Add SKU").clicked(){let p=&self.new_product;if p.sku.trim().is_empty()||p.name.trim().is_empty()||self.state.products.iter().any(|x|x.sku.eq_ignore_ascii_case(p.sku.trim())){self.status="Enter a unique SKU and product name".into()}else{self.state.products.push(p.clone());self.new_product.sku.clear();self.new_product.name.clear();changed=true;self.status="SKU added".into();}}});if changed{self.save()} }
fn cart_ui(ui:&mut egui::Ui,products:&[Product],cart:&mut Vec<(String,i32)>){let mut remove=None;for (i,(sku,q)) in cart.iter_mut().enumerate(){if let Some(p)=products.iter().find(|p|p.sku==*sku){ui.horizontal(|ui|{ui.label(format!("{} · PHP {:.2}",p.name,p.price));if ui.button("−").clicked(){*q-=1}ui.label(q.to_string());if ui.button("+").clicked() && *q<p.stock {*q+=1}if ui.button("Remove").clicked(){remove=Some(i)}});if *q<=0{remove=Some(i)}}}if let Some(i)=remove {cart.remove(i);} }
fn pos(&mut self,ui:&mut egui::Ui) {ui.heading("Walk-in Counter POS");ui.horizontal(|ui|{ui.label("Search SKU or product");ui.text_edit_singleline(&mut self.pos_search);});let q=self.pos_search.to_lowercase();egui::ScrollArea::vertical().max_height(200.0).show(ui,|ui|{for p in self.state.products.iter().filter(|p|p.sku.to_lowercase().contains(&q)||p.name.to_lowercase().contains(&q)){ui.horizontal(|ui|{ui.label(format!("{} · {} · PHP {:.2} · {} available",p.sku,p.name,p.price,p.stock));if ui.add_enabled(p.stock>0,egui::Button::new("Add")).clicked(){Self::add(&mut self.pos_cart,p);}});}});ui.separator();Self::cart_ui(ui,&self.state.products,&mut self.pos_cart);let total=self.total(&self.pos_cart);ui.strong(format!("Total PHP {total:.2}"));ui.horizontal(|ui|{for (i,t) in ["Cash","GCash QR","Card"].iter().enumerate(){ui.selectable_value(&mut self.tender,i,*t);}});if self.tender==0 {ui.horizontal(|ui|{ui.label("Cash received PHP");ui.add(egui::DragValue::new(&mut self.cash).range(0.0..=1_000_000.0));ui.label(format!("Change PHP {:.2}",(self.cash-total).max(0.0)));});} else if self.tender==1 {ui.label("Confirm payment using your merchant GCash QR before completing the sale.");} if ui.button("Complete sale").clicked(){self.checkout(true)} }
fn forecast(&mut self,ui:&mut egui::Ui) {ui.heading("Demand forecasting");if self.models.is_none(){if ui.button("Train models").clicked(){self.models=Some(ml::train());}ui.label("Train on the first 80% of the embedded chronological dataset; evaluate on the remaining 20%.");return}let m=self.models.as_ref().unwrap();ui.label("1,200 records · 960 training / 240 held out");ui.horizontal_wrapped(|ui|{for (name,s) in [("Linear Regression",&m.linear_metrics),("Random Forest",&m.forest_metrics)] {ui.group(|ui|{ui.strong(name);ui.label(format!("MAE {:.4}   RMSE {:.4}   R² {:.4}",s.mae,s.rmse,s.r2));});}});ui.separator();ui.heading("Scenario predictor");ui.horizontal(|ui|{ui.selectable_value(&mut self.model,0,"Linear regression");ui.selectable_value(&mut self.model,1,"Random forest");});for (i,label) in ["Unit price PHP","Promotion (0 or 1)","Seasonality","Previous month demand"].iter().enumerate(){ui.horizontal(|ui|{ui.label(*label);ui.add(egui::DragValue::new(&mut self.scenario[i]).range(0.0..=100000.0).speed(0.1));});}let prediction=if self.model==0 {m.linear.predict(&self.scenario)}else{m.forest.predict(&self.scenario)};ui.strong(format!("Predicted demand: {prediction:.1} · {} velocity",if prediction>=80.0{"High"}else if prediction>=40.0{"Moderate"}else{"Low"}));ui.separator();ui.label("Held-out actual vs predicted · green actual, amber predicted");let (rect,_)=ui.allocate_exact_size(egui::vec2(ui.available_width().max(100.0),200.0),egui::Sense::hover());let painter=ui.painter();painter.rect_filled(rect,4.0,ui.visuals().extreme_bg_color);let max=m.test.iter().map(|p|p.y.max(if self.model==0{m.linear.predict(&p.x)}else{m.forest.predict(&p.x)})).fold(1.0,f64::max);for i in 1..m.test.len(){let coord=|idx:usize,v:f64|egui::pos2(rect.left()+rect.width()*idx as f32/(m.test.len()-1) as f32,rect.bottom()-rect.height()*(v/max) as f32);let a=m.test[i-1];let b=m.test[i];let predict=|p:ml::Point|if self.model==0 {m.linear.predict(&p.x)}else{m.forest.predict(&p.x)};painter.line_segment([coord(i-1,a.y),coord(i,b.y)],egui::Stroke::new(1.0,Color32::from_rgb(53,151,100)));painter.line_segment([coord(i-1,predict(a)),coord(i,predict(b))],egui::Stroke::new(1.0,Color32::from_rgb(220,150,49)));}if ui.button("Export model artifacts to JSON").clicked(){let data=serde_json::json!({"linear":m.linear,"forest":m.forest,"linear_metrics":m.linear_metrics,"forest_metrics":m.forest_metrics});self.status=match std::fs::write("goodstock_models.json",serde_json::to_string_pretty(&data).unwrap_or_default()){Ok(())=>"Exported goodstock_models.json".into(),Err(e)=>format!("Export failed: {e}")};} }
fn poll_sync(&mut self) {if let Some(rx)=&self.sync {match rx.try_recv(){Ok(Ok(items))=>{let mut updated=0;for item in &items {let name=item["title"].as_str().unwrap_or("");if let Some(p)=self.state.products.iter_mut().find(|p|p.name==name){if let Some(desc)=item["description"].as_str(){p.description=desc.to_owned();}if let Some(cat)=item["productType"].as_str(){p.category=cat.to_owned();}updated+=1;}}self.status=format!("Synced metadata for {updated} matching products; local stock and prices retained");self.sync=None;self.save();},Ok(Err(e))=>{self.status=format!("Sync failed: {e}");self.sync=None;},Err(mpsc::TryRecvError::Disconnected)=>{self.status="Sync worker stopped".into();self.sync=None;},Err(mpsc::TryRecvError::Empty)=>{}}}}
}
impl eframe::App for App {fn update(&mut self,ctx:&egui::Context,_frame:&mut eframe::Frame){self.poll_sync();if self.sync.is_some(){ctx.request_repaint_after(std::time::Duration::from_millis(200));}egui::TopBottomPanel::top("top").show(ctx,|ui|{ui.horizontal(|ui|{theme::brand(ui);ui.vertical(|ui|{ui.strong("GOODSTOCK");ui.small("HARDWARE");});ui.separator();self.nav(ui,Page::Home,"Home");self.nav(ui,Page::Shop,"Shop");self.nav(ui,Page::History,"Orders");if self.signed_in=="admin@goodstock.ph" {ui.separator();self.nav(ui,Page::Overview,"Overview");self.nav(ui,Page::Inventory,"Inventory");self.nav(ui,Page::Pos,"Counter POS");self.nav(ui,Page::Forecast,"Forecast");}ui.with_layout(egui::Layout::right_to_left(egui::Align::Center),|ui|{if ui.button(if self.dark{"☀ Light"}else{"☾ Dark"}).clicked(){self.dark=!self.dark;theme::apply(ctx,self.dark)}if ui.button(format!("Cart ({})",self.cart.iter().map(|(_,q)|q).sum::<i32>())).clicked(){self.drawer=!self.drawer}if self.signed_in.is_empty(){if ui.button("Sign in").clicked(){self.login=true}}else if ui.button(format!("Sign out ({})",self.signed_in)).clicked(){self.signed_in.clear();self.page=Page::Home;}});});});egui::TopBottomPanel::bottom("status").show(ctx,|ui|{ui.horizontal(|ui|{ui.label(&self.status);if ui.add_enabled(self.sync.is_none(),egui::Button::new("Sync catalog")).clicked(){self.sync=Some(api::sync());self.status="Syncing catalog…".into();}});});if self.drawer {egui::SidePanel::right("cart").resizable(true).default_width(340.0).show(ctx,|ui|{ui.heading("Your cart");Self::cart_ui(ui,&self.state.products,&mut self.cart);ui.separator();ui.strong(format!("Total PHP {:.2}",self.total(&self.cart)));ui.label("Fulfillment");ui.radio_value(&mut self.delivery,0,"Counter Pickup");ui.radio_value(&mut self.delivery,1,"Local Courier Delivery");if ui.button("Place order").clicked(){self.checkout(false)}if ui.button("Close").clicked(){self.drawer=false}});}
egui::CentralPanel::default().show(ctx,|ui|{ui.add_space(10.0);match self.page {Page::Home=>{ui.label(RichText::new("YOUR NEIGHBORHOOD HARDWARE STORE").strong());ui.add_space(18.0);ui.heading(RichText::new("Good tools. Better projects.").size(36.0));ui.label("Dependable hardware for every repair, build, and idea.");ui.add_space(18.0);if ui.button("Explore the shop →").clicked(){self.page=Page::Shop}ui.add_space(30.0);ui.heading("Shop by aisle");ui.columns(3,|cols|{for (i,cat) in ["Fasteners","Tools","Power & Electrical"].iter().enumerate(){cols[i].group(|ui|{ui.set_min_height(100.0);ui.heading(*cat);ui.label("Explore the essentials");if ui.button("Browse →").clicked(){self.category=(*cat).into();self.page=Page::Shop}});}});},Page::Shop=>self.catalog(ui),Page::History=>{ui.heading("Order history & receipts");egui::ScrollArea::vertical().show(ui,|ui|{for o in self.state.orders.iter().rev().filter(|o|self.signed_in=="admin@goodstock.ph" || o.customer==self.signed_in){ui.group(|ui|{ui.strong(format!("{} · PHP {:.2}",o.number,o.total));ui.label(format!("{} · {}",o.method,if o.customer.is_empty(){"Guest"}else{&o.customer}));for (sku,q,price) in &o.items {ui.label(format!("{sku} × {q} · PHP {price:.2} each"));}});}});},Page::Overview=>{ui.heading("Executive Overview");let units:i32=self.state.products.iter().map(|p|p.stock).sum();let value:f64=self.state.products.iter().map(|p|p.price*p.stock as f64).sum();let sales:f64=self.state.orders.iter().map(|o|o.total).sum();ui.horizontal_wrapped(|ui|{for (k,v) in [("Active SKUs",self.state.products.len().to_string()),("Units on hand",units.to_string()),("Retail inventory value",format!("PHP {value:.2}")),("Recorded sales",format!("PHP {sales:.2}"))]{ui.group(|ui|{ui.label(k);ui.heading(v);});}});ui.add_space(20.0);ui.heading("Low-stock replenishment queue");for p in self.state.products.iter().filter(|p|p.stock<=p.max_stock/4){ui.label(format!("{} · {} on hand · suggested {}",p.name,p.stock,(p.max_stock-p.stock).max(0)));}},Page::Inventory=>self.inventory(ui),Page::Pos=>self.pos(ui),Page::Forecast=>{egui::ScrollArea::vertical().show(ui,|ui|self.forecast(ui));}}});
if let Some(i)=self.details {let mut open=true;egui::Window::new("Product specifications").open(&mut open).show(ctx,|ui|{if let Some(p)=self.state.products.get(i){ui.heading(&p.name);ui.label(format!("{} · {}",p.sku,p.category));ui.label(&p.description);ui.strong(format!("PHP {:.2} · {} in stock",p.price,p.stock));if ui.add_enabled(p.stock>0,egui::Button::new("Add to cart")).clicked(){Self::add(&mut self.cart,p)}}});if !open {self.details=None}}
if self.login {let mut open=true;egui::Window::new(if self.register{"Create account"}else{"Sign in"}).open(&mut open).show(ctx,|ui|{ui.label("Email");ui.text_edit_singleline(&mut self.email);ui.label("Password");ui.add(egui::TextEdit::singleline(&mut self.password).password(true));if ui.button(if self.register{"Register"}else{"Sign in"}).clicked(){let email=self.email.trim().to_lowercase();if self.register {if email.is_empty()||self.password.is_empty()||email=="admin@goodstock.ph"||self.state.accounts.iter().any(|a|a.email==email){self.status="Enter a unique email and password".into()}else{self.state.accounts.push(Account{email:email.clone(),password:self.password.clone()});self.signed_in=email;self.password.clear();self.login=false;self.save();}}else if (email=="admin@goodstock.ph"&&self.password=="password123")||self.state.accounts.iter().any(|a|a.email==email&&a.password==self.password){self.signed_in=email;self.password.clear();self.login=false;}else{self.status="Invalid credentials".into();}}if ui.button(if self.register{"Already registered? Sign in"}else{"Create customer account"}).clicked(){self.register=!self.register;}ui.small("Accounts are stored locally on this device.");});if !open{self.login=false;}}
}}
